// Put the live state into the page and return it as HTML.
//
// Generated by n8n/dashboard/build.py from n8n/dashboard/page.html. Edit the
// page and rebuild; do not edit the template string by hand.
//
// The JSON is escaped for a <script> element, because handles and error
// messages come from outside and "</script>" in one would end the block.
// The replacement is a function, because a replacement string would read
// "$'" inside the data as a pattern.

const TEMPLATE = "<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>Creator program</title>
<style>
:root{
  --bg:#f6f6f3;--surface:#fff;--line:#e8e7e2;--line-2:#d8d7d0;
  --text:#191917;--muted:#6b6a64;--faint:#9a9992;
  --accent:#4338ca;--accent-soft:#eef0ff;--on-accent:#fff;
  --ok:#15803d;--ok-soft:#e9f5ed;--warn:#b45309;--warn-soft:#fdf3e4;
  --bad:#b91c1c;--bad-soft:#fdeded;--idle:#77766f;--idle-soft:#efeeea;
  --r:14px;--mono:ui-monospace,"SF Mono","Cascadia Mono",Consolas,monospace;
}
@media (prefers-color-scheme:dark){:root{
  --bg:#111110;--surface:#1a1a18;--line:#292926;--line-2:#363632;
  --text:#ecebe6;--muted:#a3a29b;--faint:#74736d;
  --accent:#a5b4fc;--accent-soft:#222540;--on-accent:#111110;
  --ok:#4ade80;--ok-soft:#14261a;--warn:#fbbf24;--warn-soft:#2a2113;
  --bad:#f87171;--bad-soft:#2c1717;--idle:#a3a29b;--idle-soft:#23231f;
}}
*{box-sizing:border-box}
[hidden]{display:none!important}
html,body{margin:0;background:var(--bg);color:var(--text)}
body{font:15px/1.55 ui-sans-serif,system-ui,-apple-system,"Segoe UI",Inter,Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.wrap{max-width:1180px;margin:0 auto;padding:28px 24px 48px}
h1,h2,h3{margin:0;font-weight:600;letter-spacing:-.01em}
h1{font-size:20px}h2{font-size:17px}h3{font-size:15px}
a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}
p{margin:0}
.num{font-variant-numeric:tabular-nums}
.muted{color:var(--muted)}.faint{color:var(--faint)}
code{font-family:var(--mono);font-size:12.5px}

.top{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:22px}
.brand{display:flex;align-items:center;gap:12px}
.mark{width:34px;height:34px;border-radius:10px;background:var(--accent);position:relative}
.mark:after{content:"";position:absolute;inset:9px;border:2.5px solid var(--on-accent);border-radius:50%;border-right-color:transparent}
.sub{margin-top:2px;font-size:13px;color:var(--muted)}
.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.inline{display:inline;margin:0}

.btn{font:inherit;font-size:14px;font-weight:500;border-radius:10px;padding:8px 14px;border:1px solid var(--line-2);background:var(--surface);color:var(--text);cursor:pointer}
.btn:hover{border-color:var(--faint)}
.btn:disabled{opacity:.5;cursor:not-allowed}
.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.btn.small{font-size:13px;padding:5px 10px;border-radius:8px}

.live{display:inline-flex;align-items:center;gap:7px;font-size:13px;color:var(--muted);padding:0 6px}
.pulse{width:8px;height:8px;border-radius:50%;background:var(--ok)}
.live.off .pulse{background:var(--idle)}

.flash{border-radius:12px;padding:11px 14px;margin:0 0 18px;font-size:14px;background:var(--accent-soft);border:1px solid color-mix(in srgb,var(--accent) 25%,transparent)}
.flash.warn{background:var(--warn-soft);border-color:color-mix(in srgb,var(--warn) 30%,transparent)}
.flash.bad{background:var(--bad-soft);border-color:color-mix(in srgb,var(--bad) 30%,transparent)}

.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-bottom:28px}
.kpi{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}
.kpi .l{font-size:12.5px;color:var(--muted)}
.kpi .v{font-size:26px;font-weight:600;letter-spacing:-.02em;margin:4px 0 2px}
.kpi .f{font-size:12.5px;color:var(--faint)}
.kpi.bad .v{color:var(--bad)}.kpi.ok .v{color:var(--ok)}

.section{margin-bottom:30px}
.section-head{margin-bottom:12px}
.section-head p{margin-top:3px;color:var(--muted);font-size:14px;max-width:760px}
.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:18px 20px;min-width:0}
.card+.card{margin-top:14px}
.grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,330px),1fr));gap:14px}
.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,460px),1fr));gap:14px}
.empty{color:var(--muted);font-size:14px}

/* the three workflows */
.wf-head{display:flex;align-items:center;gap:10px;margin-bottom:6px}
.badge{display:inline-grid;place-items:center;min-width:30px;height:24px;padding:0 6px;border-radius:7px;font-size:12px;font-weight:700;background:var(--accent-soft);color:var(--accent);font-family:var(--mono)}
.when{margin-left:auto;font-size:12px;color:var(--muted);background:var(--idle-soft);border-radius:999px;padding:2px 9px;white-space:nowrap}
.wf-desc{font-size:13.5px;color:var(--muted);margin-bottom:12px}
.steps{list-style:none;margin:0;padding:0;position:relative}
.steps li{position:relative;padding:0 0 14px 30px}
.steps li:last-child{padding-bottom:4px}
.steps li:before{content:attr(data-n);position:absolute;left:0;top:1px;width:20px;height:20px;border-radius:50%;background:var(--surface);border:1.5px solid var(--line-2);font-size:11px;font-weight:600;display:grid;place-items:center;color:var(--muted)}
.steps li:not(:last-child):after{content:"";position:absolute;left:10px;top:23px;bottom:2px;width:1.5px;background:var(--line)}
.steps b{display:block;font-size:14px;font-weight:600}
.steps span{display:block;font-size:13px;color:var(--muted)}
.ex{display:block;margin-top:5px;font-size:12.5px;background:var(--bg);border:1px dashed var(--line-2);border-radius:8px;padding:5px 9px;color:var(--text);overflow-wrap:anywhere}
.ex:before{content:"Ejemplo real · ";color:var(--faint)}
.sample .ex:before{content:"Ejemplo · "}
.wf-foot{margin-top:10px;font-size:13px}

/* the rules */
.scale{display:flex;border-radius:10px;overflow:hidden;margin:4px 0 6px;height:34px;font-size:12.5px;font-weight:600}
.scale div{flex:1;display:flex;align-items:center;justify-content:center;color:#fff;padding:0 6px;text-align:center}
.ticks{display:flex;justify-content:space-between;font-size:12px;color:var(--muted);margin-bottom:16px}
.ticks span{flex:1;text-align:center}.ticks span:first-child{text-align:left}.ticks span:last-child{text-align:right}
.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}
.col{border:1px solid var(--line);border-top:4px solid var(--c);border-radius:12px;padding:12px 14px;background:var(--bg)}
.col h3{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.col h3 .num{font-size:20px}
.col .why{font-size:12.5px;color:var(--muted);margin:2px 0 4px}
.col .next{font-size:12.5px;color:var(--text);margin-bottom:10px}
.chip{display:flex;justify-content:space-between;gap:8px;align-items:baseline;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:6px 9px;margin-top:6px;font-size:13px}
.chip small{color:var(--muted);font-size:12px;text-align:right;overflow-wrap:anywhere}

/* one creator, end to end */
.journey{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}
@media (max-width:900px){.journey{grid-template-columns:1fr}}
.journey li{position:relative;border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:var(--bg)}
@media (min-width:901px){.journey li:not(:last-child):after{content:"";position:absolute;right:-8px;top:24px;width:6px;height:6px;border-top:1.5px solid var(--faint);border-right:1.5px solid var(--faint);transform:rotate(45deg)}}
.journey .k{font-size:11.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--faint);font-weight:600}
.journey .v{font-size:17px;font-weight:600;margin:3px 0}
.journey p{font-size:12.5px;color:var(--muted)}
.formula{margin-top:14px;padding:14px 16px;border-radius:12px;background:var(--accent-soft);font-size:15px;display:flex;flex-wrap:wrap;gap:6px 10px;align-items:baseline}
.formula b{font-size:20px}
.formula .op{color:var(--muted)}
.formula small{flex-basis:100%;color:var(--muted);font-size:12.5px}

/* payouts */
.bars{display:flex;flex-direction:column;gap:8px}
.barrow{display:grid;grid-template-columns:110px 1fr 90px;gap:10px;align-items:center;font-size:13px}
.track{height:12px;background:var(--idle-soft);border-radius:6px;overflow:hidden}
.fill{height:100%;background:var(--accent);border-radius:6px;min-width:3px}

/* failures */
.row{display:flex;align-items:flex-start;gap:12px;padding:11px 0;border-bottom:1px solid var(--line)}
.row:last-child{border-bottom:0}
.grow{flex:1;min-width:0}
.pill{display:inline-block;font-size:12px;font-weight:500;border-radius:999px;padding:1px 8px;white-space:nowrap}
.p-ok{background:var(--ok-soft);color:var(--ok)}.p-warn{background:var(--warn-soft);color:var(--warn)}
.p-bad{background:var(--bad-soft);color:var(--bad)}.p-idle{background:var(--idle-soft);color:var(--muted)}
.err{font-family:var(--mono);font-size:12px;color:var(--muted);margin-top:4px;overflow-wrap:anywhere}
.todo{font-size:12.5px;margin-top:4px}
.todo:before{content:"Qué hacer: ";font-weight:600}
.right{display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.meta{font-size:12px;color:var(--faint);white-space:nowrap}
.legend-reasons{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:8px;margin-bottom:12px}
.legend-reasons div{font-size:12.5px;color:var(--muted)}

.tablewrap{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:14px}
th{text-align:left;font-size:12px;font-weight:500;color:var(--muted);padding:0 10px 8px;border-bottom:1px solid var(--line)}
td{padding:10px;border-bottom:1px solid var(--line)}
tr:last-child td{border-bottom:0}
th.r,td.r{text-align:right}

.foot{display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;font-size:12.5px;color:var(--faint);margin-top:22px}
.foot nav{display:flex;gap:12px;flex-wrap:wrap}
</style>
</head>
