<div class="wrap" id="wrap">

  <header class="top">
    <div class="brand">
      <div class="mark" aria-hidden="true"></div>
      <div>
        <h1>Creator program</h1>
        <p class="sub" id="source"></p>
      </div>
    </div>
    <div class="actions" id="actions">
      <span class="live" id="live" role="status"><span class="pulse"></span><span id="live-text"></span></span>
      <button class="btn" id="pause" type="button"></button>
    </div>
  </header>

  <div class="flash" id="flash" role="status" hidden></div>
  <div class="flash warn" id="sample" hidden>Vista previa con datos inventados. Abierta desde n8n, esta página muestra los datos reales de la base de datos.</div>

  <section class="kpis" id="kpis" aria-label="Resumen"></section>

  <section class="section">
    <div class="section-head">
      <h2>Cómo funciona</h2>
      <p>Todo el programa son tres automatizaciones de n8n. Cada paso lleva debajo un caso real sacado de la base de datos.</p>
    </div>
    <div class="grid3" id="how"></div>
  </section>

  <section class="section">
    <div class="section-head">
      <h2>Las reglas de selección</h2>
      <p id="rules-sub"></p>
    </div>
    <div class="card">
      <div class="scale" id="scale" role="img"></div>
      <div class="ticks" id="ticks"></div>
      <div class="cols" id="cols"></div>
    </div>
  </section>

  <section class="section">
    <div class="section-head">
      <h2>Un creador, de principio a fin</h2>
      <p>El recorrido completo de un caso real: el creador con más visitas.</p>
    </div>
    <div class="card" id="journey"></div>
  </section>

  <div class="grid2 section">
    <section>
      <div class="section-head">
        <h2>Pagos por mes</h2>
        <p>Lo que <b>02 payout</b> calculó para cada mes. No se transfiere nada automáticamente.</p>
      </div>
      <div class="card" id="payouts"></div>
    </section>

    <section>
      <div class="section-head">
        <h2>Fallos pendientes</h2>
        <p>Lo que necesita a una persona. Cuando esté resuelto, márcalo.</p>
      </div>
      <div class="card" id="dls"></div>
    </section>
  </div>

  <section class="section">
    <div class="section-head">
      <h2>Creadores</h2>
      <p>Dados de alta, con lo que han publicado y su último pago.</p>
    </div>
    <div class="card tablewrap" id="creators"></div>
  </section>

  <footer class="foot" id="foot"></footer>
</div>

<script>const STATE = /*__STATE__*/null;</script>
<script>
(function () {
  'use strict';

  // The data arrives embedded in the page, rendered by n8n. No fetch: n8n
  // serves webhook HTML sandboxed with an opaque origin, where a fetch back
  // would fail. Actions are plain form posts and "live" is a reload.
  //
  // Everything from the database is untrusted (handles, error messages), so
  // nothing here uses innerHTML. Text goes in through textContent only.

  var REFRESH_SECONDS = 15;
  var ACTION_URL = '/webhook/creator-program/dashboard/action';
  var WF = { pipeline: 'creatorPipeline1', payout: 'creatorPayout002', errors: 'creatorErrors003' };

  var S = STATE || sample();
  var isSample = !STATE;
  var R = S.rules || {};

  // es-ES leaves four-digit numbers ungrouped ("5000" next to "20.000"); force it.
  var nf = new Intl.NumberFormat('es-ES', { useGrouping: 'always' });
  var eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', useGrouping: 'always' });
  var dayFmt = new Intl.DateTimeFormat('es-ES', { day: 'numeric', month: 'short', year: 'numeric' });
  var monthFmt = new Intl.DateTimeFormat('es-ES', { month: 'long', year: 'numeric', timeZone: 'UTC' });
  var timeFmt = new Intl.DateTimeFormat('es-ES', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

  var LABEL = { accepted: 'aceptada', review: 'a revisión', rejected: 'rechazada', invalid: 'inválida' };

  // ---- helpers -------------------------------------------------------------

  function h(tag, props) {
    var e = document.createElement(tag);
    props = props || {};
    Object.keys(props).forEach(function (k) {
      var v = props[k];
      if (v == null) return;
      if (k === 'text') e.textContent = String(v);
      else if (k === 'class') e.className = v;
      else e.setAttribute(k, String(v));
    });
    for (var i = 2; i < arguments.length; i++) {
      var c = arguments[i];
      if (c == null || c === false) continue;
      e.appendChild(typeof c === 'object' ? c : document.createTextNode(String(c)));
    }
    return e;
  }

  function frag() {
    var f = document.createDocumentFragment();
    for (var i = 0; i < arguments.length; i++) if (arguments[i]) f.appendChild(arguments[i]);
    return f;
  }

  function mount(id, node) {
    var root = document.getElementById(id);
    root.textContent = '';
    if (node) root.appendChild(node);
    return root;
  }

  function safeHref(u) {
    try {
      var x = new URL(String(u));
      return x.protocol === 'https:' ? x.href : null;
    } catch (e) { return null; }
  }

  function wfLink(id, label) {
    var base = safeHref(S.editor_base_url);
    if (!base) return h('span', { class: 'faint', text: label });
    return h('a', { href: new URL('/workflow/' + id, base).href, target: '_blank', rel: 'noopener', text: label });
  }

  function ago(ts) {
    if (!ts) return '';
    var s = Math.max(0, Math.round((Date.now() - new Date(ts).getTime()) / 1000));
    if (s < 60) return 'hace ' + s + ' s';
    var m = Math.round(s / 60);
    if (m < 60) return 'hace ' + m + ' min';
    var hr = Math.round(m / 60);
    if (hr < 48) return 'hace ' + hr + ' h';
    return 'hace ' + Math.round(hr / 24) + ' días';
  }

  function n(x) { return nf.format(Number(x || 0)); }
  function euros(cents) { return eur.format(Number(cents || 0) / 100); }
  function day(ts) { return ts ? dayFmt.format(new Date(ts)) : '—'; }
  function month(p) { return p ? monthFmt.format(new Date(p.period_start)) : '—'; }

  // The same arithmetic as the SQL in 02 payout: integer cents, rounded half up.
  function owed(views, rate) { return Math.floor((Number(views) * Number(rate) + 500) / 1000); }

  function totalApplicants() {
    var f = S.funnel || {};
    return (f.accepted || 0) + (f.review || 0) + (f.rejected || 0) + (S.invalid_total || 0);
  }

  // ---- page state carried in the URL hash ---------------------------------
  // localStorage throws in a sandboxed page; the hash survives the reload.

  var hp = new URLSearchParams(location.hash.slice(1));
  var paused = hp.get('p') === '1';
  var flashKey = hp.get('f');

  function hashFor() {
    var p = new URLSearchParams();
    p.set('y', String(Math.round(window.scrollY)));
    if (paused) p.set('p', '1');
    return '#' + p.toString();
  }

  // ---- actions ---------------------------------------------------------------
  // Each form carries a token that only this rendered page knows. Basic auth
  // alone would let any other site post here with the saved login.

  function actionForm(action, label, cls, extra) {
    var f = h('form', { method: 'post', action: ACTION_URL, class: 'inline' });
    f.appendChild(h('input', { type: 'hidden', name: 'action', value: action }));
    f.appendChild(h('input', { type: 'hidden', name: 'token', value: S.action_token || '' }));
    Object.keys(extra || {}).forEach(function (k) {
      f.appendChild(h('input', { type: 'hidden', name: k, value: extra[k] }));
    });
    var b = h('button', { type: 'submit', class: 'btn ' + (cls || ''), text: label });
    if (isSample) { b.disabled = true; b.title = 'No disponible en la vista previa'; }
    f.addEventListener('submit', function () { stopTimer(); b.disabled = true; b.textContent = 'Un momento…'; });
    f.appendChild(b);
    return f;
  }

  // ---- header and numbers -----------------------------------------------------

  function renderHeader() {
    document.getElementById('source').textContent = isSample
      ? 'Vista previa'
      : 'En vivo desde n8n · base de datos creator_prod';
    document.getElementById('actions').appendChild(actionForm('run', 'Lanzar el pipeline ahora', 'primary'));
  }

  function renderKpis() {
    var f = S.funnel || {};
    var last = (S.periods || [])[0];
    var open = S.dead_letters_open || 0;
    var box = document.createDocumentFragment();
    function kpi(label, value, foot, tone) {
      box.appendChild(h('div', { class: 'kpi ' + (tone || '') },
        h('div', { class: 'l', text: label }),
        h('div', { class: 'v num', text: value }),
        h('div', { class: 'f', text: foot })));
    }
    kpi('Solicitudes', n(totalApplicants()), n(f.review) + ' esperando a una persona');
    kpi('Creadores', n((S.creators || []).length), 'dados de alta');
    kpi('Visitas rastreadas', n(S.views_total), 'en ' + n(S.posts_total) + ' posts');
    kpi('Último pago calculado', last ? euros(last.total_cents) : '—', last ? month(last) : 'aún ningún mes');
    kpi('Fallos pendientes', n(open), open ? 'ver abajo qué hacer' : 'todo en orden', open ? 'bad' : 'ok');
    mount('kpis', box);
  }

  // ---- how it works -------------------------------------------------------------

  function workflowCard(num, title, when, desc, steps, id) {
    var ol = h('ol', { class: 'steps' });
    steps.forEach(function (s, i) {
      ol.appendChild(h('li', { 'data-n': i + 1 },
        h('b', { text: s[0] }),
        h('span', { text: s[1] }),
        s[2] ? h('span', { class: 'ex', text: s[2] }) : null));
    });
    return h('div', { class: 'card' },
      h('div', { class: 'wf-head' }, h('span', { class: 'badge', text: num }), h('h3', { text: title }), h('span', { class: 'when', text: when })),
      h('p', { class: 'wf-desc', text: desc }),
      ol,
      h('div', { class: 'wf-foot' }, wfLink(id, 'Abrir en n8n →')));
  }

  function firstExample() {
    var ex = S.examples || {};
    var order = ['accepted', 'review', 'rejected'];
    for (var i = 0; i < order.length; i++) {
      var list = ex[order[i]] || [];
      if (list.length) return [order[i], list[0]];
    }
    return null;
  }

  function renderHow() {
    var j = S.journey;
    var fe = firstExample();
    var periods = S.periods || [];
    var dl = (S.dead_letters || [])[0];

    var brake;
    if (periods[0] && periods[1]) {
      var ratio = Number(periods[0].total_cents) / Math.max(1, Number(periods[1].total_cents));
      brake = month(periods[0]) + ': ' + euros(periods[0].total_cents) + ' frente a ' + euros(periods[1].total_cents) +
        ' el mes anterior (' + ratio.toFixed(1).replace('.', ',') + '×) → ' + (ratio > Number(R.payout_sanity_multiplier) ? 'retenido' : 'dentro de lo normal');
    } else if (periods[0]) {
      brake = month(periods[0]) + ': ' + euros(periods[0].total_cents) + ', sin mes anterior con el que comparar';
    }

    var calc = j && j.payout
