    remaining = REFRESH_SECONDS;
    renderLive();
    timer = setInterval(function () {
      remaining -= 1;
      if (remaining <= 0) {
        stopTimer();
        location.replace(location.pathname + location.search + hashFor());
        location.reload();
        return;
      }
